// 输入: SQL 查询结果 (msg.payload = rows array)
// 输出: 按设备分组，每个点位附加模拟值

const rows = msg.payload || [];
const devices = {};

for (const row of rows) {
    const did = row.device_id;
    if (!devices[did]) {
        devices[did] = {
            device_id: did,
            device_name: row.device_name,
            device_code: row.device_code,
            plc_brand: row.plc_brand,
            plc_series: row.plc_series,
            com_type: row.com_type,
            plc_ip: row.plc_ip,
            plc_port: row.plc_port,
            mc_frame: row.mc_frame,
            station_no: row.station_no,
            network_no: row.network_no,
            scan_interval_ms: row.scan_interval_ms,
            comm_timeout_ms: row.comm_timeout_ms,
            retry_count: row.retry_count,
            trigger_kind: row.trigger_kind,
            tags: []
        };
    }

    let mockValue;
    switch ((row.data_type || '').toUpperCase()) {
        case 'INT16':
            mockValue = Math.floor(Math.random() * 65535) - 32768;
            break;
        case 'INT32':
            mockValue = Math.floor(Math.random() * 4294967295) - 2147483648;
            break;
        case 'FLOAT':
            mockValue = parseFloat((Math.random() * 1000).toFixed(2));
            break;
        case 'BIT':
            mockValue = Math.random() > 0.5 ? 1 : 0;
            break;
        default:
            mockValue = Math.floor(Math.random() * 100);
    }

    devices[did].tags.push({
        tag_id: row.tag_id,
        tag_name: row.tag_name,
        register_type: row.register_type,
        register_address: row.register_address,
        data_type: row.data_type,
        unit: row.unit || '',
        value: mockValue,
        timestamp: new Date().toISOString()
    });
}

const result = Object.values(devices);
msg.payload = result;
msg.deviceCount = result.length;
msg.tagCount = rows.length;

node.status({
    fill: 'green',
    shape: 'dot',
    text: `${result.length}设备 ${rows.length}点位 @ ${new Date().toLocaleTimeString()}`
});

return msg;
